package blockbranch.metallurgy;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.*;
import net.minecraft.core.registries.*;
import net.minecraft.resources.RegistryOps;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.damagesource.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.*;
import net.minecraft.world.item.enchantment.*;
/** Real native damage and smithing paths, including nominal armor-cost rounding and death/loot ordering. */
public final class UraniumWeaponSmoke {
 static void require(boolean b,String m){RadiationSmoke.require(b,m);}
 static int enchants(ItemStack s){return s.getOrDefault(DataComponents.ENCHANTMENTS,ItemEnchantments.EMPTY).keySet().size();}
 static void seed(LivingEntity e,boolean strip,boolean irradiate){for(int i=0;i<100000;i++){e.getRandom().setSeed(i);boolean a=e.getRandom().nextFloat()<UraniumCombat.STRIP_CHANCE;boolean b=e.getRandom().nextFloat()<UraniumCombat.IRRADIATE_CHANCE;if(a==strip&&b==irradiate){e.getRandom().setSeed(i);return;}}throw new AssertionError("bounded deterministic random fixture");}
 public static void verify(ServerLevel l,Path directory)throws Exception{
  var manager=l.getServer().getRecipeManager();var registry=l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT);var unbreaking=registry.getOrThrow(Enchantments.UNBREAKING);Item[] bases={Items.NETHERITE_SWORD,Items.NETHERITE_AXE,Items.NETHERITE_SPEAR},upgrades={UraniumContent.SWORD,UraniumContent.AXE,UraniumContent.SPEAR};
  var ops=RegistryOps.create(net.minecraft.nbt.NbtOps.INSTANCE,l.registryAccess());
  for(int i=0;i<3;i++){
   var original=new ItemStack(bases[i]);original.setDamageValue(17);original.enchant(unbreaking,2);original.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Keeper"));var before=original.copy();var input=new SmithingRecipeInput(new ItemStack(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),original,new ItemStack(UraniumContent.TIP));var result=manager.getRecipeFor(RecipeType.SMITHING,input,l).orElseThrow().value().assemble(input);require(result.is(upgrades[i])&&result.getDamageValue()==17&&result.getEnchantments().getLevel(unbreaking)==2&&result.get(DataComponents.CUSTOM_NAME).getString().equals("Keeper")&&ItemStack.isSameItemSameComponents(original,before),"native smithing preserves base without mutation");
   for(var c:bases[i].components())if(c.type()!=DataComponents.ITEM_NAME&&c.type()!=DataComponents.ITEM_MODEL&&c.type()!=DataComponents.LORE)require(Objects.equals(upgrades[i].components().get(c.type()),c.value()),"native weapon component parity "+c.type());require(new ItemStack(upgrades[i]).isValidRepairItem(new ItemStack(Items.NETHERITE_INGOT)),"native netherite repair");for(var enchantment:registry.listElements().toList())require(enchantment.value().canEnchant(new ItemStack(bases[i]))==enchantment.value().canEnchant(new ItemStack(upgrades[i])),"native enchant eligibility parity "+enchantment.key());var saved=directory.resolve("uranium-weapon-"+i+".dat");if(Files.exists(saved)){var prior=ItemStack.CODEC.parse(ops,net.minecraft.nbt.NbtIo.readCompressed(saved,net.minecraft.nbt.NbtAccounter.unlimitedHeap())).getOrThrow();require(ItemStack.isSameItemSameComponents(prior,result),"weapon native damage/enchant/name relaunch");}net.minecraft.nbt.NbtIo.writeCompressed((net.minecraft.nbt.CompoundTag)ItemStack.CODEC.encodeStart(ops,result).getOrThrow(),saved);
  }
  require(manager.getRecipeFor(RecipeType.SMITHING,new SmithingRecipeInput(new ItemStack(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE),new ItemStack(Items.IRON_SWORD),new ItemStack(UraniumContent.TIP)),l).isEmpty(),"no early iron upgrade");require(manager.getRecipeFor(RecipeType.SMITHING,new SmithingRecipeInput(ItemStack.EMPTY,new ItemStack(Items.NETHERITE_SWORD),new ItemStack(UraniumContent.TIP)),l).isEmpty(),"native template required");
  for(int i=0;i<3;i++)for(float amount:new float[]{2,8,17}){
   int[] wear=new int[2];for(int k=0;k<2;k++){var victim=RadiationSmoke.player(l);RadiationSmoke.equip(victim,"minecraft:iron");victim.setHealth(20);var attacker=EntityTypes.ZOMBIE.create(l,EntitySpawnReason.COMMAND);attacker.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(k==0?bases[i]:upgrades[i]));seed(attacker,false,false);var source=i==2?new DamageSource(l.registryAccess().lookupOrThrow(Registries.DAMAGE_TYPE).getOrThrow(DamageTypes.SPEAR),attacker):l.damageSources().mobAttack(attacker);require(victim.hurtServer(l,source,amount),"positive native weapon damage");wear[k]=victim.getItemBySlot(EquipmentSlot.CHEST).getDamageValue();}require(wear[1]==wear[0]*3&&wear[0]>0,"exact triple rounded nominal armor wear "+amount+" baseline="+wear[0]+" tipped="+wear[1]);
  }
  var attacker=EntityTypes.ZOMBIE.create(l,EntitySpawnReason.COMMAND);attacker.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(UraniumContent.SWORD));var victim=RadiationSmoke.player(l);var gear=new ItemStack(Items.DIAMOND_PICKAXE);gear.enchant(unbreaking,2);gear.enchant(registry.getOrThrow(Enchantments.EFFICIENCY),3);victim.setItemSlot(EquipmentSlot.MAINHAND,gear);seed(attacker,true,false);require(victim.hurtServer(l,l.damageSources().mobAttack(attacker),2)&&enchants(gear)==1,"one enchantment permanently removed on successful native hit");var stripped=directory.resolve("uranium-stripped.dat");if(Files.exists(stripped)){var prior=ItemStack.CODEC.parse(ops,net.minecraft.nbt.NbtIo.readCompressed(stripped,net.minecraft.nbt.NbtAccounter.unlimitedHeap())).getOrThrow();require(enchants(prior)==1&&(prior.getEnchantments().getLevel(unbreaking)==2||prior.getEnchantments().getLevel(registry.getOrThrow(Enchantments.EFFICIENCY))==3),"stripped enchantment persists through relaunch without assuming new JVM choice order");}net.minecraft.nbt.NbtIo.writeCompressed((net.minecraft.nbt.CompoundTag)ItemStack.CODEC.encodeStart(ops,gear).getOrThrow(),stripped);
  for(boolean expect:new boolean[]{false,true}){var p=RadiationSmoke.player(l);seed(attacker,false,expect);p.hurtServer(l,l.damageSources().mobAttack(attacker),2);require(p.hasEffect(UraniumContent.RADIATION)==expect,"high chance includes native success and failure controls");}
  var shielded=RadiationSmoke.player(l);RadiationSmoke.equip(shielded,"minecraft:diamond");seed(attacker,false,true);shielded.hurtServer(l,l.damageSources().mobAttack(attacker),2);require(!shielded.hasEffect(UraniumContent.RADIATION),"fully qualifying target cannot be irradiated");
  int[] atDeath={-1};var dying=new net.minecraft.world.entity.player.Player(l,new com.mojang.authlib.GameProfile(new UUID(0,999),"UraniumDeathProbe")){@Override public net.minecraft.world.level.GameType gameMode(){return net.minecraft.world.level.GameType.SURVIVAL;}@Override public void die(DamageSource source){atDeath[0]=enchants(getMainHandItem());super.die(source);}};var loot=new ItemStack(Items.DIAMOND_PICKAXE);loot.enchant(unbreaking,2);dying.setItemSlot(EquipmentSlot.MAINHAND,loot);dying.setHealth(1);seed(attacker,true,false);dying.hurtServer(l,l.damageSources().mobAttack(attacker),4);require(!dying.isAlive()&&atDeath[0]==0,"lethal hit strips before native death/loot");
  var ordinary=RadiationSmoke.player(l);var untouched=new ItemStack(Items.DIAMOND_PICKAXE);untouched.enchant(unbreaking,2);ordinary.setItemSlot(EquipmentSlot.MAINHAND,untouched);attacker.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.NETHERITE_SWORD));seed(attacker,true,true);ordinary.hurtServer(l,l.damageSources().mobAttack(attacker),2);require(enchants(untouched)==1&&!ordinary.hasEffect(UraniumContent.RADIATION),"ordinary netherite has no uranium mechanics");attacker.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(UraniumContent.SWORD));require(!UraniumCombat.weaponHit(l.damageSources().thorns(attacker)),"thorns is not a weapon hit");
  blockbranch.Blockbranch.LOGGER.info("URANIUM native smithing/components, triple rounded armor wear, enchant strip/reload/lethal order and irradiation controls passed");
 }
 private UraniumWeaponSmoke(){}
}
